NEW_FILES = {'tests/test_floor_by_use.py': '"""A selling floor is tile and a working floor is concrete, whatever role routes it to carpet (0.271.0).\n\nThe walker, 2026-10-26: "far too dark in teh super market". The sales floor read luma p50 3 against the back stock\'s\n77; it was carpeted maroon because `public_entry` maps to carpet (the factory\'s docs/findings/walk_2026-10-26_panel/,\nL4). FAILS ON 0.270.0.\n"""\nimport glob\nimport json\nimport os\nimport sys\nfrom types import SimpleNamespace\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\n\nimport floors  # noqa: E402\n\n\ndef _room(rid, role, **kw):\n    return SimpleNamespace(id=rid, role=role, **kw)\n\n\ndef _floor(room):\n    return floors._material(room, "floor", floors.FLOOR_BY_ROLE, "concrete")\n\n\ndef test_the_supermarkets_sales_floor_is_tile():\n    assert _floor(_room("sales_floor", "public_entry")) == "tile"\n\n\ndef test_stores_sell_on_tile_and_work_on_concrete():\n    for rid in ("customer_floor", "shop_floor", "retail_floor", "stall_floor", "market_aisles"):\n        assert _floor(_room(rid, "public_entry")) == "tile", rid\n    for rid in ("stockroom_loading", "service_bay", "garage_bay", "deck_0_south", "dock_floor", "shed_floor",\n                "lanes", "ground_works", "ground_pour"):\n        assert _floor(_room(rid, "public_entry")) == "concrete", rid\n\n\ndef test_a_lobby_a_banking_hall_and_a_parlour_keep_their_carpet():\n    for rid in ("lobby", "grand_lobby", "banking_hall", "parlor", "lounge", "waiting_room", "main_floor"):\n        assert _floor(_room(rid, "public_entry")) == "carpet", rid\n\n\ndef test_only_a_carpet_is_reconsidered_and_a_rooms_own_floor_wins():\n    assert _floor(_room("stockroom", "fortifiable")) == "concrete"          # the map\'s own answer\n    assert _floor(_room("sales_floor", "route_node")) == "tile"             # the map\'s own answer\n    assert _floor(_room("sales_floor", "public_entry", floor_material="wood")) == "wood"\n    assert floors._material(_room("sales_floor", "public_entry"), "ceiling", floors.CEILING_BY_ROLE,\n                            "concrete") == "ceiling_tile"                   # the ceiling is not touched\n\n\ndef test_no_selling_or_working_floor_in_the_library_is_carpeted():\n    carpeted = []\n    for path in sorted(glob.glob(os.path.join(ROOT, "specs", "*.json"))):\n        try:\n            spec = json.load(open(path, encoding="utf-8"))\n        except (OSError, ValueError):\n            continue\n        for r in spec.get("rooms") or []:\n            room = SimpleNamespace(id=r.get("id"), role=r.get("role"), floor_material=r.get("floor_material"),\n                                   material=r.get("material"))\n            if floors.floor_by_use(r.get("id")) and _floor(room) == "carpet":\n                carpeted.append("%s/%s" % (os.path.basename(path), r.get("id")))\n    assert carpeted == []\n'}
CHANGELOG = '## [0.271.0] - a selling floor is tile and a working floor is concrete\n\n**The walker, walking seed 9205\'s supermarket, 2026-10-26: "far too dark in teh super market"** (the factory\'s\n`docs/findings/walk_2026-10-26_panel/`, L4).\n\n### Measured, in order\n1. The sales floor\'s light-check station read luma p50 3 at Blue Hour; the back stock next door read 77.\n2. Not the import: a complete re-walk read the same.\n3. Not missing lamps: every lamp is baked, and the bake supplies 15.8 of the frame\'s 20.7.\n4. Re-baked copies, against a control that reproduced the shipped frame exactly: doubling the lightmap\'s texels\n   changed nothing, and doubling the room fill raised both rooms alike.\n5. Under an inspection light the sales floor is a dark maroon carpet; the back stock is pale concrete. The room was\n   lit like its neighbour and dark because of what it was made of.\n\n### Changed\n- **`floors.floor_by_use`, asked by `_material` wherever the role map would carpet a floor.**\n  - `public_entry` maps to carpet. That is right for a lobby, a banking hall or a parlour, and it had carpeted 33\n    `sales_floor`s, the delis\' `customer_floor`s and `stockroom_loading`s, pawn, pharmacy and market floors, a\n    garage deck, service bays, docks and train sheds.\n  - A room whose id SELLS (`sales`, `retail`, `shop`, `store`, `market`, `stall`, `customer`, `aisle`) now gets\n    `tile`, a 1990s store\'s vinyl tile.\n  - A room whose id WORKS (`stock`, `loading`, `dock`, `bay`, `deck`, `shed`, `lanes`, `works`, `pour`, `garage`)\n    gets `concrete`.\n  - A room\'s own floor material still wins, the ceiling is untouched, and floor and ceiling stay different surfaces.\n  - `main_floor` is left alone: it is a warehouse\'s and a club\'s both, so what it is needs the building, not the room.\n- Rebuilt library: 594 floor slots, 72 still carpet (lobbies, halls, parlours, lounges, waiting rooms, offices).\n\n### Tests\n- `tests/test_floor_by_use.py` (3 of 5 fail on 0.270.0; the other two guard lobbies and a room\'s own floor):\n  - the supermarket\'s sales floor is tile;\n  - stores sell on tile and work on concrete;\n  - a lobby, a banking hall and a parlour keep carpet;\n  - only a carpet is reconsidered, and a room\'s own floor wins;\n  - no selling or working floor in the library is carpeted.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.270.0', 'Deli Counter 0.271.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
